mapper.select:
SELECT * FROM TBL_INVEST_PROJECT

    AND COMPANY_ID = #{query.companyId}
    AND PROJECT_NAME LIKE CONCAT('%', #{query.projectName}, '%')
    AND INVEST_TYPE = #{query.investType}
    AND PROJECT_STATUS = #{query.projectStatus}

ORDER BY CREATE_TIME DESC

SELECT COMPANY_ID, COMPANY_NAME, COUNT(*) AS projectCount, SUM(INVEST_AMOUNT) AS totalAmount, SUM(CASE WHEN IS_MAIN_BUSINESS = 'N' THEN INVEST_AMOUNT ELSE 0 END) AS nonMainAmount FROM TBL_INVEST_PROJECT
AND COMPANY_ID = #{companyId}
GROUP BY COMPANY_ID, COMPANY_NAME
